package com.playercircles;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.Varbits;
import net.runelite.api.WorldType;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class PlayerCirclesOverlay extends Overlay
{
	private static final int SEGMENTS = 24;

	private static final double[] COS = new double[SEGMENTS];
	private static final double[] SIN = new double[SEGMENTS];

	static
	{
		for (int i = 0; i < SEGMENTS; i++)
		{
			double angle = 2 * Math.PI * i / SEGMENTS;
			COS[i] = Math.cos(angle);
			SIN[i] = Math.sin(angle);
		}
	}

	private final Client client;
	private final PlayerCirclesConfig config;

	@Inject
	private PlayerCirclesOverlay(Client client, PlayerCirclesConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(Overlay.PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.enable2d())
		{
			return null;
		}

		if (client.getTopLevelWorldView() == null)
		{
			return null;
		}

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		Player local = client.getLocalPlayer();

		for (Player player : client.getTopLevelWorldView().players())
		{
			if (player == null || player.getName() == null)
			{
				continue;
			}

			Color fillColor = colorFor(player, local);
			if (fillColor == null)
			{
				continue;
			}

			Color outlineColor = outlineColorFor(player, local);
			drawShadow(graphics, player, fillColor, outlineColor);
		}

		return null;
	}

	private Color colorFor(Player player, Player local)
	{
		if (player == local)
		{
			return config.drawSelf2d() ? config.selfColor2d() : null;
		}
		if (config.drawFriends2d() && player.isFriend())
		{
			return config.friendColor2d();
		}
		if (config.drawClan2d() && player.isClanMember())
		{
			return config.clanColor2d();
		}
		if (config.drawTeam2d() && player.isFriendsChatMember())
		{
			return config.teamColor2d();
		}
		if (config.drawOthersPvp2d() && isInPvpZone())
		{
			return config.otherPvpColor2d();
		}
		if (config.drawOthers2d())
		{
			return config.otherColor2d();
		}
		return null;
	}

	private Color outlineColorFor(Player player, Player local)
	{
		if (player == local)
		{
			return config.selfOutlineColor2d();
		}
		if (config.drawFriends2d() && player.isFriend())
		{
			return config.friendOutlineColor2d();
		}
		if (config.drawClan2d() && player.isClanMember())
		{
			return config.clanOutlineColor2d();
		}
		if (config.drawTeam2d() && player.isFriendsChatMember())
		{
			return config.teamOutlineColor2d();
		}
		return config.otherOutlineColor2d();
	}

	private void drawShadow(Graphics2D graphics, Player player, Color fillColor, Color outlineColor)
	{
		LocalPoint lp;
		boolean isLocalPlayer = player == client.getLocalPlayer();
		if (isLocalPlayer && config.trueTile() && client.getTopLevelWorldView() != null)
		{
			lp = LocalPoint.fromWorld(client.getTopLevelWorldView(), player.getWorldLocation());
		}
		else
		{
			lp = player.getLocalLocation();
		}

		if (lp == null)
		{
			return;
		}

		int plane = client.getTopLevelWorldView().getPlane();
		int radius = Perspective.LOCAL_TILE_SIZE * config.circleScale() / 200;

		Polygon poly = new Polygon();
		for (int i = 0; i < SEGMENTS; i++)
		{
			int x = lp.getX() + (int) (COS[i] * radius);
			int y = lp.getY() + (int) (SIN[i] * radius);
			LocalPoint edge = new LocalPoint(x, y, client.getTopLevelWorldView());

			Point canvas = Perspective.localToCanvas(client, edge, plane);
			if (canvas == null)
			{
				continue;
			}
			poly.addPoint(canvas.getX(), canvas.getY());
		}

		if (poly.npoints < 3)
		{
			return;
		}

		graphics.setColor(fillColor);
		graphics.fill(poly);

		if (config.outline2d())
		{
			graphics.setColor(outlineColor);
			float strokeWidth = config.outlineThickness2d() * 0.7f;
			if (config.dottedOutline2d())
			{
				// Measure the polygon's canvas perimeter so the segment count
				// stays visually constant regardless of camera zoom level.
				float perimeter = 0f;
				for (int i = 0; i < poly.npoints; i++)
				{
					int j = (i + 1) % poly.npoints;
					float dx = poly.xpoints[j] - poly.xpoints[i];
					float dy = poly.ypoints[j] - poly.ypoints[i];
					perimeter += (float) Math.sqrt(dx * dx + dy * dy);
				}
				// density 1 = 8 segments, density 5 = 28 segments
				int targetSegments = config.dotDensity2d() * 5 + 3;
				float period = Math.max(4f, perimeter / targetSegments);
				// 45% dash / 55% gap gives short lines with clear spacing
				graphics.setStroke(new BasicStroke(strokeWidth,
					BasicStroke.CAP_BUTT, BasicStroke.JOIN_BEVEL,
					0, new float[]{period * 0.45f, period * 0.55f}, 0f));
			}
			else
			{
				graphics.setStroke(new BasicStroke(strokeWidth));
			}
			graphics.draw(poly);
		}
	}

	private boolean isInPvpZone()
	{
		if (client.getWorldType().contains(WorldType.PVP)
			|| client.getWorldType().contains(WorldType.DEADMAN))
		{
			return true;
		}
		return client.getVarbitValue(Varbits.IN_WILDERNESS) > 0;
	}
}

