package com.playercircles;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Player Circles",
	description = "3D in-world disc and 2D overlay ring under players. Per-type colors for self, friends, clan, team, and PVP. True tile, dashed outline, boss fights.",
	tags = {"shadow", "circle", "indicator", "player", "soul wars", "deadman", "pvp", "wilderness", "nightmare", "boss", "highlight", "3d", "2d", "true tile"}
)
public class PlayerCirclesPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PlayerCirclesOverlay overlay;

	@Inject
	private CircleSceneManager sceneManager;

	@Inject
	private ClientThread clientThread;

	@Provides
	PlayerCirclesConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PlayerCirclesConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		// CircleSceneManager accesses the client scene — must run on client thread
		clientThread.invoke(sceneManager::startUp);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clientThread.invoke(sceneManager::shutDown);
	}
}

