import net.runelite.api.WorldType;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.PlayerDespawned;
import net.runelite.api.events.PlayerSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

@Slf4j
class CircleSceneManager
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private PlayerCirclesConfig config;

	@Inject
	private EventBus eventBus;

	/** Main fill disc, one per tracked player. */
	private final Map<Player, RuneLiteObject> objects = new HashMap<>();
	/**
	 * Approach-B fallback outline ring (larger disc, outline-colored, rendered beneath fill).
	 * Only activated when Approach A cannot obtain face index data.
	 */
	private final Map<Player, RuneLiteObject> outlineObjects = new HashMap<>();

	/** Cache for plain fill models (no baked outline). */
	private final Map<Long, Model> modelCache = new HashMap<>();
	/** Cache for Approach-A baked models (per-face rim coloring). */
	private final Map<Long, Model> approachACache = new HashMap<>();
	/** Keys for which Approach A was attempted and the model lacked face indices. */
	private final Set<Long> approachAFailedKeys = new HashSet<>();
	/** Cache for Approach-B outline ring models. */
	private final Map<Long, Model> outlineModelCache = new HashMap<>();

	// -------------------------------------------------------------------------
	// Lifecycle
	// -------------------------------------------------------------------------

	void startUp()
	{
		eventBus.register(this);
		if (client.getTopLevelWorldView() == null)
		{
			return;
		}
		for (Player p : client.getTopLevelWorldView().players())
		{
			if (p != null)
			{
				spawnDisc(p);
			}
		}
	}

	void shutDown()
	{
		eventBus.unregister(this);
		clearAll();
		modelCache.clear();
		approachACache.clear();
		approachAFailedKeys.clear();
		outlineModelCache.clear();
	}

	// -------------------------------------------------------------------------
	// Events
	// -------------------------------------------------------------------------

	@Subscribe
	public void onPlayerSpawned(PlayerSpawned event)
	{
		spawnDisc(event.getPlayer());
	}

	@Subscribe
	public void onPlayerDespawned(PlayerDespawned event)
	{
		despawnDisc(event.getPlayer());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN
			|| state == GameState.HOPPING
			|| state == GameState.LOADING)
		{
			clearAll();
		}
		else if (state == GameState.LOGGED_IN)
		{
			// After a teleport the local player may not fire PlayerSpawned again.
			// Re-scan all players in the current world view to restore any missing discs.
			if (client.getTopLevelWorldView() != null)
			{
				for (Player p : client.getTopLevelWorldView().players())
				{
					if (p != null)
					{
						spawnDisc(p);
					}
				}
			}
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (client.getTopLevelWorldView() == null)
		{
			return;
		}
		Player local = client.getLocalPlayer();
		int plane = client.getTopLevelWorldView().getPlane();
		boolean is3d = config.enable3d();

		for (Map.Entry<Player, RuneLiteObject> entry : objects.entrySet())
		{
			Player player = entry.getKey();
			RuneLiteObject obj = entry.getValue();
			RuneLiteObject outlineObj = outlineObjects.get(player);

			if (!is3d)
			{
				obj.setActive(false);
				if (outlineObj != null)
				{
					outlineObj.setActive(false);
				}
				continue;
			}

			Color color = colorFor(player, local);
			if (color == null)
			{
				obj.setActive(false);
				if (outlineObj != null)
				{
					outlineObj.setActive(false);
				}
				continue;
			}

			// Approach A: single model, per-face outline baked in.
			boolean approachAUsed = false;
			Model model = null;
			if (config.outline())
			{
				Color outlineColor = outlineColorFor3d(player, local);
				model = getOrBuildModelWithApproachA(color, outlineColor);
				approachAUsed = (model != null);
			}
			// Outline off, or A unavailable (no face indices) -- use plain fill.
			if (model == null)
			{
				model = getOrBuildModel(color);
			}

			if (model == null)
			{
				obj.setActive(false);
				if (outlineObj != null)
				{
					outlineObj.setActive(false);
				}
				continue;
			}
			obj.setModel(model);

			LocalPoint lp = getPlayerLocalPoint(player);
			if (lp != null)
			{
				obj.setLocation(lp, plane);
				int groundZ = Perspective.getTileHeight(client, lp, plane);
				obj.setZ(groundZ);
				obj.setActive(true);

				// Approach B: separate ring, only when A is unavailable.
				if (outlineObj != null)
				{
					if (config.outline() && !approachAUsed)
					{
						Color outlineColor = outlineColorFor3d(player, local);
						Model outlineModel = getOrBuildOutlineModel(outlineColor);
						if (outlineModel != null)
						{
							outlineObj.setModel(outlineModel);
							outlineObj.setLocation(lp, plane);
							outlineObj.setZ(groundZ);
							outlineObj.setActive(true);
						}
						else
						{
							outlineObj.setActive(false);
						}
					}
					else
					{
						outlineObj.setActive(false);
					}
				}
			}
			else
			{
				obj.setActive(false);
				if (outlineObj != null)
				{
					outlineObj.setActive(false);
				}
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals("playercircles"))
		{
			return;
		}

		String key = event.getKey();

		if (key.equals("circleScale")
			|| key.equals("selfColor")
			|| key.equals("friendColor")
			|| key.equals("clanColor")
			|| key.equals("teamColor")
			|| key.equals("otherColor")
			|| key.equals("otherPvpColor")
			|| key.equals("discModel")
			|| key.equals("groundOffset")
			|| key.equals("outline")
			|| key.equals("outlineThickness")
			|| key.equals("selfOutlineColor")
			|| key.equals("friendOutlineColor")
			|| key.equals("clanOutlineColor")
			|| key.equals("teamOutlineColor")
			|| key.equals("otherOutlineColor"))
		{
			modelCache.clear();
			approachACache.clear();
			approachAFailedKeys.clear();
			outlineModelCache.clear();
		}
	}

	// -------------------------------------------------------------------------
	// Internal
	// -------------------------------------------------------------------------

	private void spawnDisc(Player player)
	{
		if (objects.containsKey(player))
		{
			return;
		}

		RuneLiteObject obj = client.createRuneLiteObject();
		RuneLiteObject outlineObj = client.createRuneLiteObject();

		Player local = client.getLocalPlayer();
		Color color = colorFor(player, local);
		boolean in3d = config.enable3d();

		Model model = null;
		if (color != null && in3d)
		{
			if (config.outline())
			{
				Color outlineColor = outlineColorFor3d(player, local);
				model = getOrBuildModelWithApproachA(color, outlineColor);
			}
			if (model == null)
			{
				model = getOrBuildModel(color);
			}
		}
		if (model != null)
		{
			obj.setModel(model);
		}

		LocalPoint lp = getPlayerLocalPoint(player);
		if (lp != null && client.getTopLevelWorldView() != null)
		{
			int plane = client.getTopLevelWorldView().getPlane();
			int groundZ = Perspective.getTileHeight(client, lp, plane);
			obj.setLocation(lp, plane);
			obj.setZ(groundZ);
			outlineObj.setLocation(lp, plane);
			outlineObj.setZ(groundZ);
		}

		boolean active = in3d && model != null && lp != null;
		obj.setActive(active);
		outlineObj.setActive(false);
		objects.put(player, obj);
		outlineObjects.put(player, outlineObj);
	}

	private void despawnDisc(Player player)
	{
		RuneLiteObject obj = objects.remove(player);
		if (obj != null)
		{
			obj.setActive(false);
		}
		RuneLiteObject outlineObj = outlineObjects.remove(player);
		if (outlineObj != null)
		{
			outlineObj.setActive(false);
		}
	}

	private void clearAll()
	{
		for (RuneLiteObject obj : objects.values())
		{
			obj.setActive(false);
		}
		objects.clear();
		for (RuneLiteObject obj : outlineObjects.values())
		{
			obj.setActive(false);
		}
		outlineObjects.clear();
	}

	// -------------------------------------------------------------------------
	// Model builders
	// -------------------------------------------------------------------------

	/**
	 * Approach A: colors each face individually by its XZ centroid distance from
	 * the disc origin. Faces in the outer band get the outline color; inner faces
	 * get the fill color. This gives smooth, linear thickness control with no
	 * face-color-group quantization artifacts.
	 *
	 * Each thickness unit covers 5% of the disc radius:
	 *   t=1  -> rim starts at 95% of maxR (thin ring at edge)
	 *   t=10 -> rim starts at 50% of maxR (half the disc)
	 *
	 * Returns null only if the model lacks face index data (Approach B activates).
	 */
	private Model getOrBuildModelWithApproachA(Color fillColor, Color outlineColor)
	{
		long key = approachAKey(fillColor, outlineColor);

		if (approachAFailedKeys.contains(key))
		{
			return null;
		}

		Model cached = approachACache.get(key);
		if (cached != null)
		{
			return cached;
		}

		ModelData data = loadAndScaleDisc(config.circleScale(), config.groundOffset());
		if (data == null)
		{
			approachAFailedKeys.add(key);
			return null;
		}

		int[] fi1 = data.getFaceIndices1();
		int[] fi2 = data.getFaceIndices2();
		int[] fi3 = data.getFaceIndices3();
		float[] vx = data.getVerticesX();
		float[] vz = data.getVerticesZ();

		if (fi1 == null || fi2 == null || fi3 == null || vx == null || vz == null)
		{
			log.debug("PlayerCircles: face indices unavailable for model {}; falling back to B",
				config.discModel().getModelId());
			approachAFailedKeys.add(key);
			return null;
		}

		short[] faceColorsArr = data.getFaceColors();
		if (faceColorsArr == null || faceColorsArr.length == 0)
		{
			approachAFailedKeys.add(key);
			return null;
		}

		// Find max face-centroid radius in the scaled model.
		float maxR = 0f;
		for (int i = 0; i < faceColorsArr.length; i++)
		{
			float cx = (vx[fi1[i]] + vx[fi2[i]] + vx[fi3[i]]) / 3f;
			float cz = (vz[fi1[i]] + vz[fi2[i]] + vz[fi3[i]]) / 3f;
			float r2 = cx * cx + cz * cz;
			if (r2 > maxR)
			{
				maxR = r2;
			}
		}
		maxR = (float) Math.sqrt(maxR);

		if (maxR == 0f)
		{
			approachAFailedKeys.add(key);
			return null;
		}

		// t=1: threshold at 95% -> outermost 5% of radius is rim.
		// t=10: threshold at 50% -> outermost 50% is rim.
		float rimThreshold = maxR * (1.0f - config.outlineThickness() * 0.05f);

		short fillHsl = JagexColor.rgbToHSL(fillColor.getRGB(), 1.0);
		short outlineHsl = JagexColor.rgbToHSL(outlineColor.getRGB(), 1.0);
		// Rim faces use outline alpha; interior faces use fill alpha.
		byte fillT = (byte) (255 - fillColor.getAlpha());
		byte outlineT = (byte) (255 - outlineColor.getAlpha());

		data = data.cloneColors();
		short[] fc = data.getFaceColors();
		data = data.cloneTransparencies(true);
		byte[] ft = data.getFaceTransparencies();

		for (int i = 0; i < fc.length; i++)
		{
			float cx = (vx[fi1[i]] + vx[fi2[i]] + vx[fi3[i]]) / 3f;
			float cz = (vz[fi1[i]] + vz[fi2[i]] + vz[fi3[i]]) / 3f;
			float r = (float) Math.sqrt(cx * cx + cz * cz);
			boolean rim = (r >= rimThreshold);
			fc[i] = rim ? outlineHsl : fillHsl;
			if (ft != null && i < ft.length)
			{
				ft[i] = rim ? outlineT : fillT;
			}
		}

		Model model = data.light();
		approachACache.put(key, model);
		return model;
	}

	/** Plain fill model (no baked outline). */
	private Model getOrBuildModel(Color color)
	{
		long key = cacheKey(color, config.circleScale(), config.discModel(), config.groundOffset());
		Model cached = modelCache.get(key);
		if (cached != null)
		{
			return cached;
		}

		ModelData data = loadAndScaleDisc(config.circleScale(), config.groundOffset());
		if (data == null)
		{
			return null;
		}

		data = recolor(data, color);
		data = applyTransparency(data, color.getAlpha());

		Model model = data.light();
		modelCache.put(key, model);
		return model;
	}

	/**
	 * Approach-B fallback: larger disc recolored to outlineColor, lifted 2 units
	 * less so depth-sorting shows only the protruding rim. Used only when the
	 * model lacks face index data and Approach A is unavailable.
	 */
	private Model getOrBuildOutlineModel(Color outlineColor)
	{
		int outlineScale = config.circleScale() * (100 + config.outlineThickness() * 3) / 100;
		int outlineOffset = Math.max(0, config.groundOffset() - 2);

		long key = cacheKey(outlineColor, outlineScale, config.discModel(), outlineOffset);
		Model cached = outlineModelCache.get(key);
		if (cached != null)
		{
			return cached;
		}

		ModelData data = loadAndScaleDisc(outlineScale, outlineOffset);
		if (data == null)
		{
			return null;
		}

		data = recolor(data, outlineColor);
		data = applyTransparency(data, outlineColor.getAlpha());

		Model model = data.light();
		outlineModelCache.put(key, model);
		return model;
	}

	// ---- Shared build helpers ----

	private ModelData loadAndScaleDisc(int circleScale, int groundOffset)
	{
		int modelId = config.discModel().getModelId();
		ModelData data = client.loadModelData(modelId);
		if (data == null)
		{
			log.warn("PlayerCircles: loadModelData({}) returned null -- try the other disc shape.", modelId);
			return null;
		}

		int targetRadius = Perspective.LOCAL_TILE_SIZE * circleScale / 200;
		float[] vx = data.getVerticesX();
		float[] vz = data.getVerticesZ();
		float maxR = 1f;
		int vertCount = data.getVerticesCount();
		for (int i = 0; i < vertCount; i++)
		{
			float r = (float) Math.sqrt(vx[i] * vx[i] + vz[i] * vz[i]);
			if (r > maxR)
			{
				maxR = r;
			}
		}
		int scaleFactor = Math.max(1, Math.round(targetRadius * 128f / maxR));

		data = data.cloneVertices();
		data.scale(scaleFactor, 4, scaleFactor);

		float yShift = -(float) groundOffset;
		float[] vy = data.getVerticesY();
		int count = data.getVerticesCount();
		for (int i = 0; i < count; i++)
		{
			vy[i] += yShift;
		}

		return data;
	}

	private ModelData recolor(ModelData data, Color color)
	{
		short targetHsl = JagexColor.rgbToHSL(color.getRGB(), 1.0);
		short[] faceColors = data.getFaceColors();
		if (faceColors != null && faceColors.length > 0)
		{
			Set<Short> seen = new HashSet<>();
			for (short c : faceColors)
			{
				seen.add(c);
			}
			data = data.cloneColors();
			for (short original : seen)
			{
				data.recolor(original, targetHsl);
			}
		}
		return data;
	}

	private ModelData applyTransparency(ModelData data, int javaAlpha)
	{
		byte osrsTransparency = (byte) (255 - javaAlpha);
		data = data.cloneTransparencies(true);
		byte[] ft = data.getFaceTransparencies();
		if (ft != null)
		{
			Arrays.fill(ft, osrsTransparency);
		}
		return data;
	}

	// ---- Cache keys ----
	//
	// Bit layout for cacheKey (64 bits, no overlaps):
	//   [63..40] RGB  (24 bits)
	//   [39..32] alpha (8 bits)
	//   [31..24] scale clamped to 8 bits (range 20-200 fits in 8 bits)
	//   [23..16] model ordinal (8 bits, currently 0-1)
	//   [15.. 8] groundOffset (8 bits, range 0-32)
	//   [ 7.. 0] unused / zero

	private static long cacheKey(Color color, int scale, DiscModel model, int groundOffset)
	{
		return ((long) (color.getRGB() & 0xFFFFFF) << 40)
			| ((long) (color.getAlpha() & 0xFF) << 32)
			| ((long) (scale & 0xFF) << 24)
			| ((long) (model.ordinal() & 0xFF) << 16)
			| ((long) (groundOffset & 0xFF) << 8);
	}

	private long approachAKey(Color fillColor, Color outlineColor)
	{
		// Multiplicative hash: fold fill key, outline RGBA, and thickness
		// together without bit-overlap issues.
		long h = cacheKey(fillColor, config.circleScale(), config.discModel(), config.groundOffset());
		h = h * 31 + (outlineColor.getRGB() & 0xFFFFFF);
		h = h * 31 + outlineColor.getAlpha();
		h = h * 31 + config.outlineThickness();
		return h;
	}

	// ---- Player color helpers ----

	/**
	 * Returns the local point to use for disc placement.
	 * True tile mode snaps to the server-confirmed tile; smooth uses the
	 * interpolated client position for fluid movement.
	 */
	private LocalPoint getPlayerLocalPoint(Player player)
	{
		return player.getLocalLocation();
	}

	private Color colorFor(Player player, Player local)
	{
		if (player == local)
		{
			return config.drawSelf() ? config.selfColor() : null;
		}
		if (config.drawFriends() && player.isFriend())
		{
			return config.friendColor();
		}
		if (config.drawClan() && player.isClanMember())
		{
			return config.clanColor();
		}
		if (config.drawTeam() && player.isFriendsChatMember())
		{
			return config.teamColor();
		}
		if (config.drawOthersPvp() && isInPvpZone())
		{
			return config.otherPvpColor();
		}
		if (config.drawOthers())
		{
			return config.otherColor();
		}
		return null;
	}

	/** Returns the per-player-type outline color for 3D mode. */
	private Color outlineColorFor3d(Player player, Player local)
	{
		if (player == local)
		{
			return config.selfOutlineColor();
		}
		if (config.drawFriends() && player.isFriend())
		{
			return config.friendOutlineColor();
		}
		if (config.drawClan() && player.isClanMember())
		{
			return config.clanOutlineColor();
		}
		if (config.drawTeam() && player.isFriendsChatMember())
		{
			return config.teamOutlineColor();
		}
		return config.otherOutlineColor();
	}

	private boolean isInPvpZone()
	{
		if (client.getWorldType().contains(WorldType.PVP)
			|| client.getWorldType().contains(WorldType.DEADMAN))
		{
			return true;
		}
		return client.getVarbitValue(Varbits.IN_WILDERNESS) > 0;
	}
}
